starter_code:
function remise(prix, pourcentage) {
  return prix;
}

function appliquerRemises(prix, calcul) {
  return 0;
}

solution:
function remise(prix: number, pourcentage = 10): number {
  return prix - Math.round(prix * pourcentage / 100);
}

function appliquerRemises(prix: number[], calcul: (p: number) => number): number {
  return prix.map(calcul).reduce((s, p) => s + p, 0);
}
